/**
 * The TypeScript side checked against the Go side.
 *
 * `recovery/testdata/vectors.json` is generated by `recovery/vectors_test.go`
 * and read by both. Neither implementation is the reference for the other; both
 * answer to the file.
 *
 * This is the test that would have caught every incompatibility found while
 * writing this port, and there were three real ones — Argon2 parallelism,
 * a 16-byte salt limit, and an AEAD with no associated data — each of which
 * produced code that looked correct, passed its own round-trip test, and could
 * not open a blob the other side had written.
 *
 * That is the shape of the danger. A round trip within one language proves
 * nothing about agreement, and agreement is the only property that matters
 * here: the device seals, the services store, and the device opens again on
 * different hardware months later.
 */
import { strict as assert } from 'node:assert';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

import { Xchacha20poly1305Ietf } from '@cosmjs/crypto';

import { depositDigest, type Holding } from './deposit.ts';
import { argonSalt, SEAL_MEMORY_KIB, SEAL_THREADS, SEAL_TIME } from './seal.ts';
import { combine, type Share } from './shamir.ts';

const here = dirname(fileURLToPath(import.meta.url));
const VECTORS = join(here, '../../../../recovery/testdata/vectors.json');

interface Vectors {
  note: string;
  argonSalt: { salt: string; expect: string }[];
  seal: {
    password: string;
    secret: string;
    salt: string;
    nonce: string;
    time: number;
    memory: number;
    threads: number;
    expect: string;
  }[];
  combine: { shares: { x: number; y: string }[]; expect: string }[];
  /** A Holding exactly as the services marshal one. */
  wire: {
    role: string;
    salt: string;
    nonce: string;
    time: number;
    memory: number;
    threads: number;
    share: { x: number; y: string };
  };
  digest: {
    email: string;
    role: string;
    pubkey: string;
    salt: string;
    nonce: string;
    time: number;
    memory: number;
    threads: number;
    share: { x: number; y: string };
    expect: string;
  }[];
}

const vectors: Vectors = JSON.parse(readFileSync(VECTORS, 'utf8'));

function hex(s: string): Uint8Array {
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function toHex(b: Uint8Array): string {
  return Array.from(b, (n) => n.toString(16).padStart(2, '0')).join('');
}

test('the vector file is populated, so nothing below passes vacuously', () => {
  assert.ok(vectors.argonSalt.length > 0, 'no argonSalt vectors');
  assert.ok(vectors.seal.length > 0, 'no seal vectors');
  assert.ok(vectors.combine.length > 0, 'no combine vectors');
  assert.ok(vectors.digest.length > 0, 'no digest vectors');
});

test('the parameters this build uses are the ones the vectors were made with', () => {
  // The seal vectors carry their own parameters, so they would still pass if
  // this file's constants drifted away from Go's — and then every account
  // enrolled here would be sealed differently from every account the services
  // expect. Checked explicitly.
  for (const v of vectors.seal) {
    assert.equal(v.time, SEAL_TIME, 'SEAL_TIME has drifted from the Go constant');
    assert.equal(v.memory, SEAL_MEMORY_KIB, 'SEAL_MEMORY_KIB has drifted from the Go constant');
    assert.equal(v.threads, SEAL_THREADS, 'SEAL_THREADS has drifted from the Go constant');
  }
});

test('argonSalt matches Go, and is exactly the 16 bytes libsodium demands', () => {
  for (const [i, v] of vectors.argonSalt.entries()) {
    const got = argonSalt(hex(v.salt));
    assert.equal(
      got.length,
      16,
      `argonSalt[${i}] is ${got.length} bytes; libsodium throws on anything but 16`,
    );
    assert.equal(toHex(got), v.expect, `argonSalt[${i}] disagrees with Go`);
  }
});

test('a sealed ciphertext byte-matches the one Go produced', async () => {
  // The expensive one: a 128 MiB Argon2id derivation per vector. It is also the
  // only test that proves an account sealed in this browser can be opened by
  // anything else, so it is the one worth waiting for.
  const { Argon2id } = await import('@cosmjs/crypto');
  for (const [i, v] of vectors.seal.entries()) {
    const key = await Argon2id.execute(v.password, argonSalt(hex(v.salt)), {
      outputLength: 32,
      opsLimit: v.time,
      memLimitKib: v.memory,
    });
    const got = await Xchacha20poly1305Ietf.encrypt(hex(v.secret), key, hex(v.nonce));
    assert.equal(toHex(got), v.expect, `seal[${i}] disagrees with Go`);
  }
});

test('a sealed ciphertext from Go opens here, back to the original secret', async () => {
  // The other direction. Encrypting to the same bytes and decrypting back are
  // not the same claim, and a recovery only ever exercises the second.
  const { Argon2id } = await import('@cosmjs/crypto');
  for (const [i, v] of vectors.seal.entries()) {
    const key = await Argon2id.execute(v.password, argonSalt(hex(v.salt)), {
      outputLength: 32,
      opsLimit: v.time,
      memLimitKib: v.memory,
    });
    const plain = await Xchacha20poly1305Ietf.decrypt(hex(v.expect), key, hex(v.nonce));
    assert.equal(toHex(plain), v.secret, `seal[${i}] did not open back to its secret`);
  }
});

test('combine reconstructs exactly what Go reconstructed', () => {
  for (const [i, v] of vectors.combine.entries()) {
    const shares: Share[] = v.shares.map((s) => ({ x: s.x, y: hex(s.y) }));
    assert.equal(toHex(combine(shares)), v.expect, `combine[${i}] disagrees with Go`);
  }
});

test('the deposit digest matches Go, including the role binding', () => {
  for (const [i, v] of vectors.digest.entries()) {
    const holding: Holding = {
      role: v.role,
      salt: hex(v.salt),
      nonce: hex(v.nonce),
      time: v.time,
      memory: v.memory,
      threads: v.threads,
      share: { x: v.share.x, y: hex(v.share.y) },
    };
    const got = depositDigest(v.email, v.role, hex(v.pubkey), holding);
    assert.equal(toHex(got), v.expect, `digest[${i}] disagrees with Go`);
  }

  // Two vectors differ only in role. If they hashed the same, the role is not
  // bound and both assertions above would pass against an implementation that
  // ignored it entirely.
  assert.notEqual(
    vectors.digest[0]!.expect,
    vectors.digest[1]!.expect,
    'the two digest vectors are identical, so they contrast nothing',
  );

  // The third differs from the first only in spelling: capitals and padding.
  // Equal digests are what prove this file folds an address exactly as Go
  // does — the failure it guards is somebody enrolling as Amara@Example.org
  // and never being able to sign in as amara@example.org.
  assert.notEqual(vectors.digest[0]!.email, vectors.digest[2]!.email, 'nothing is contrasted');
  assert.equal(
    vectors.digest[0]!.expect,
    vectors.digest[2]!.expect,
    'this build folds an email address differently from Go',
  );
});

test('a holding as the services marshal it parses here', () => {
  // The half of interoperability that arithmetic vectors do not cover, and the
  // half that broke: Go marshals an untagged struct with capitalised keys while
  // its decoder accepts lowercase ones. So a browser could enrol perfectly —
  // the direction that is easy to test — and then fail to read back the holding
  // a recovery handed it, which is the direction nobody exercises until
  // somebody has already lost their phone.
  const w = vectors.wire;
  assert.ok(w, 'no wire vector');

  // Byte arrays arrive as base64, which is how Go encodes []byte in JSON.
  const bytesOf = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
  const holding: Holding = {
    role: w.role,
    salt: bytesOf(w.salt),
    nonce: bytesOf(w.nonce),
    time: w.time,
    memory: w.memory,
    threads: w.threads,
    share: { x: w.share.x, y: bytesOf(w.share.y) },
  };

  assert.equal(holding.salt.length, 16, 'the salt did not survive the wire');
  assert.equal(holding.nonce.length, 24, 'the nonce did not survive the wire');
  assert.equal(holding.share.x, 2);
  assert.ok(holding.share.y.length > 0, 'the share bytes did not survive the wire');
  assert.equal(holding.threads, SEAL_THREADS);
  assert.equal(holding.memory, SEAL_MEMORY_KIB);

  // And it is usable: a digest over it is what this browser would sign.
  const digest = depositDigest('amara@example.org', holding.role, new Uint8Array(33), holding);
  assert.equal(digest.length, 32);
});
